    for t in P.get('tassels', []):
        img, px, py = sprite(d, cache, 'prop.swinging-tassel', t['w'])
        layer.alpha_composite(img, (int(t['x'] - px), int(t['y'] - py)))
        if lines:
            dr.line([(t['x'], t['y']), (t['x'], t['y'] - t['lift'])], fill=(255, 255, 0, 200), width=2)
